"""Generates docs/CLASS_COVERAGE_AUDIT.md from saved audit/split files (no model run)."""
import json
import pandas as pd

m = pd.read_csv("artifacts/audits/dataset_manifest.csv", dtype={"image_id": str})
b = pd.read_csv("artifacts/splits/protocolB_seed4242.csv", dtype={"image_id": str})
c = pd.read_csv("artifacts/splits/protocolC_seed777.csv", dtype={"image_id": str})
raw = m.groupby("class_id").size().rename("raw")
use = m[m.dup_status != "excluded"].groupby("class_id").size().rename("usable")
ex = m[m.dup_status == "excluded"].groupby("class_id").size().rename("excluded")
lab = m.drop_duplicates("class_id").set_index("class_id")[["raw_class_label", "crop", "healthy_by_name"]]
t = lab.join(raw).join(use).join(ex).fillna({"excluded": 0}).astype({"excluded": int})
t["primary"] = t.usable >= 13
rb = b.groupby(["class_id", "role_B"]).size().unstack(fill_value=0)
t = t.join(rb[["train_B", "gallery_B", "dev_query_B", "test_query_B"]], how="left").fillna(0)
t["test_query_C"] = c[c.role_C == "test_query_C"].groupby("class_id").size().reindex(t.index).fillna(0)
for k in ["train_B", "gallery_B", "dev_query_B", "test_query_B", "test_query_C"]: t[k] = t[k].astype(int)
ps = pd.read_csv("artifacts/external/plantseg_leak_screen.csv")
ext = ps[(ps.tier == "strict") & ~ps.leak_flag].groupby("class_id").size()
t["external_queries"] = ext.reindex(t.index).fillna(0).astype(int)
out = ["# Class coverage audit (SegPPD-101: 101 original classes vs 75 evaluated)", "",
       "Generated by `report/make_audit_md.py` from `artifacts/audits/dataset_manifest.csv`, `artifacts/splits/protocolB_seed4242.csv`, `protocolC_seed777.csv`, `artifacts/external/plantseg_leak_screen.csv`. No model was run.", "",
       "## Summary", "",
       f"* Original classes: 101 (27 are healthy-leaf classes by name); images 2,263; after removing 43 duplicate/conflict images: 2,220 usable.",
       f"* **Primary cohort = {int(t.primary.sum())} classes** with >= 13 usable images; **{int((~t.primary).sum())} classes are outside the primary evaluation** ({int(t[~t.primary].usable.min())}-{int(t[~t.primary].usable.max())} usable images).",
       "* Why 13: Protocol A needs 3 query + 10 gallery images per class; Protocol B needs 3 test + 2 dev queries and a train/gallery split of the rest with >= 4 train and >= 5 gallery positives per class. Classes below 13 cannot supply disjoint train/gallery/dev/test sets, so they were not evaluated in the primary protocols.",
       f"* Primary classes: usable images min {int(t[t.primary].usable.min())}, median {int(t[t.primary].usable.median())}, max {int(t[t.primary].usable.max())}; excluded 26 classes: min {int(t[~t.primary].usable.min())}, median {int(t[~t.primary].usable.median())}, max {int(t[~t.primary].usable.max())}.",
       f"* Healthy classes inside the primary cohort: {int(t[t.primary].healthy_by_name.sum())} of 27 (the other {27 - int(t[t.primary].healthy_by_name.sum())} healthy classes are in the excluded set).",
       "* The ~0.80 Hit@1 result is **a 75-class closed-set result** (Protocol B/C galleries contain only the 75 primary classes). It is not an evaluation over all 101 classes.",
       "* The 26 non-primary classes were only used in Protocol A's *secondary* cohort (1 query per class, training-free baselines) and are never seen by the trained models of Protocol B.", "",
       "## Per-class table", "",
       "| id | class | healthy | raw | excl. | usable | primary | train_B | gallery_B | dev_q | test_B | test_C | external q |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for cid, r in t.iterrows():
    out.append(f"| {cid} | {r.raw_class_label} | {'yes' if r.healthy_by_name else ''} | {int(r.raw)} | {int(r.excluded)} | {int(r.usable)} | {'yes' if r.primary else '**no**'} | {r.train_B} | {r.gallery_B} | {r.dev_query_B} | {r.test_query_B} | {r.test_query_C} | {r.external_queries or ''} |")
out += ["", "## Excluded (non-primary) classes", "", ", ".join(f"{r.raw_class_label} ({int(r.usable)})" for _, r in t[~t.primary].iterrows()), "",
        "## Feasibility of an all-101-class evaluation", "",
        "* Evaluating retrieval over all 101 classes **without a trained component** is possible (frozen features; the classes in the excluded set have 7-12 usable images, so queries would be 1-2 per class and recall/AP ceilings are tiny; CIs would be very wide).",
        "* A **trained** system cannot be evaluated on the 26 excluded classes with a leakage-controlled train/gallery/test protocol: a class with e.g. 4 usable images cannot give a train, gallery and test image that are also group-disjoint. Using them only as gallery/query distractors (open-set) is feasible and would test false-match behaviour, but it is a different question from closed-set Hit@1.",
        "* Therefore a fair 101-class number would need either more data for the 26 classes or a separate open-set protocol; it should not be merged with the 75-class headline."]
open("docs/CLASS_COVERAGE_AUDIT.md", "w").write("\n".join(out) + "\n")
print(t.primary.sum(), (~t.primary).sum(), t[~t.primary].usable.describe().to_dict())
